import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int r = Integer.parseInt(st.nextToken()), m = Integer.parseInt(st.nextToken());
        int[] score = new int[r], pts = {0, 10, 6, 4, 3, 2, 1};
        for (int k = 0; k < m; k++) {
            st.nextToken();  // race id is not needed
            int who = Integer.parseInt(st.nextToken()), pos = Integer.parseInt(st.nextToken());
            if (pos <= 6) score[who - 1001] += pts[pos];
        }
        int best = 0;
        for (int i = 1; i < r; i++) if (score[i] > score[best]) best = i;  // strict: smaller ID wins ties
        System.out.println((1001 + best) + " " + score[best]);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	r, m := next(), next()
	score := make([]int, r)
	pts := []int{0, 10, 6, 4, 3, 2, 1}
	for k := 0; k < m; k++ {
		next() // race id is not needed
		who, pos := next(), next()
		if pos <= 6 {
			score[who-1001] += pts[pos]
		}
	}
	best := 0
	for i := 1; i < r; i++ {
		if score[i] > score[best] { // strict: smaller ID wins ties
			best = i
		}
	}
	fmt.Println(1001+best, score[best])
}
